-- =========================================================================
-- SCRIPT SQL UNIFICADO: CONSOLIDACIÓN DE DISTRITOS, MESAS Y COLEGIOS
-- BASE DE DATOS: [conteo] | GENERADO: 2026-08-18T05:51:40.284Z
-- ID BASADO EN UBIGEO (ej. 150102-0001) Y COORDENADAS GPS INTEGRADAS
-- =========================================================================

USE [conteo];
GO

-- 1. ELIMINACIÓN DE TABLAS ANTERIORES SI YA NO SE REQUIEREN
IF OBJECT_ID(N'[dbo].[Distritos]', N'U') IS NOT NULL DROP TABLE [dbo].[Distritos];
IF OBJECT_ID(N'[dbo].[Mesas]', N'U') IS NOT NULL DROP TABLE [dbo].[Mesas];
IF OBJECT_ID(N'[dbo].[Colegios]', N'U') IS NOT NULL DROP TABLE [dbo].[Colegios];
IF OBJECT_ID(N'[dbo].[LocalesVotacion]', N'U') IS NOT NULL DROP TABLE [dbo].[LocalesVotacion];
GO

-- 2. CREACIÓN DE LA TABLA UNIFICADA [dbo].[Colegios]
CREATE TABLE [dbo].[Colegios] (
    [id] VARCHAR(20) NOT NULL PRIMARY KEY,
    [ubigeo] VARCHAR(10) NOT NULL,
    [departamento] VARCHAR(100) NOT NULL DEFAULT 'LIMA',
    [provincia] VARCHAR(100) NOT NULL DEFAULT 'LIMA',
    [distrito] VARCHAR(100) NOT NULL,
    [colegio] VARCHAR(250) NOT NULL,
    [direccion] VARCHAR(250) NULL,
    [num_mesas] INT NOT NULL DEFAULT 1,
    [latitud] DECIMAL(10,7) NULL,
    [longitud] DECIMAL(10,7) NULL,
    [coordenadas_gps] VARCHAR(100) NULL,
    [radio_metros] INT NOT NULL DEFAULT 100,
    [estado] VARCHAR(50) NOT NULL DEFAULT 'Activo',
    [fecha_registro] DATETIME NOT NULL DEFAULT GETDATE()
);
GO

-- 3. ÍNDICES DE ALTO RENDIMIENTO
CREATE INDEX IX_Colegios_Ubigeo ON [dbo].[Colegios]([ubigeo]);
CREATE INDEX IX_Colegios_Distrito ON [dbo].[Colegios]([distrito]);
CREATE INDEX IX_Colegios_Colegio ON [dbo].[Colegios]([colegio]);
GO

-- 4. VISTA DE COMPATIBILIDAD CON [dbo].[Mesas] y [dbo].[Distritos] (Opcional)
CREATE OR ALTER VIEW [dbo].[vw_Mesas] AS
SELECT [id] AS [numero_mesa], [ubigeo], [distrito], [colegio], [direccion], [departamento], [provincia], [latitud], [longitud], [coordenadas_gps], [estado]
FROM [dbo].[Colegios];
GO

